package dev.aster.charts;

import android.content.Context;
import android.os.Looper;
import org.json.*;
import java.util.*;
import java.util.function.Consumer;

/** Small full-vector initial-prepare contract tests; independent of benchmarks. */
final class PrepareVerification {
    static final String[] NAMES={"sma","ema","bollinger","macd","donchian","stochastic","rsi","atr"};
    private final JSONArray checks=new JSONArray(),jobs=new JSONArray();
    private Context context;private AsterEngine source;private Consumer<JSONObject> completion;
    private String expected,before;private boolean finished;private JSONObject mismatch;private final Map<String,byte[]> expectedBytes=new LinkedHashMap<>();
    static JSONObject options() throws JSONException {return new JSONObject().put("panels",new JSONArray().put(new JSONObject().put("id","price").put("weight",1))).put("series",new JSONArray().put(new JSONObject().put("id","price").put("type","candles").put("panel","price")));}
    static void indicators(AsterEngine e) throws JSONException {for(String name:NAMES)e.invoke("nativeIndicator",name,name,new JSONObject(),"price");}
    static double[][] fixture(int count){double[][] c=new double[6][count];for(int i=0;i<count;i++){double p=100+i*0.025;c[0][i]=1700000000000d+i*60000d;c[1][i]=p;c[2][i]=p+2;c[3][i]=p-2;c[4][i]=p+Math.sin(i*0.1);c[5][i]=1000+i;}return c;}
    static JSONObject columns(double[][] c) throws JSONException {JSONObject result=new JSONObject();String[] names={"time","open","high","low","close","volume"};for(int slot=0;slot<6;slot++){JSONArray values=new JSONArray();for(double value:c[slot])values.put(value);result.put(names[slot],values);}return result;}
    static String canonical(Object value) throws JSONException {if(value instanceof JSONObject){JSONObject object=(JSONObject)value;ArrayList<String> keys=new ArrayList<>();Iterator<String> iterator=object.keys();while(iterator.hasNext())keys.add(iterator.next());Collections.sort(keys);StringBuilder out=new StringBuilder("{");for(String key:keys){if(out.length()>1)out.append(',');out.append(JSONObject.quote(key)).append(':').append(canonical(object.get(key)));}return out.append('}').toString();}if(value instanceof JSONArray){JSONArray array=(JSONArray)value;StringBuilder out=new StringBuilder("[");for(int i=0;i<array.length();i++){if(i>0)out.append(',');out.append(canonical(array.get(i)));}return out.append(']').toString();}return value instanceof String?JSONObject.quote((String)value):String.valueOf(value);}
    static String probe(AsterEngine e) throws JSONException {JSONObject state=(JSONObject)e.command("inspect"),outputs=new JSONObject();JSONArray series=state.getJSONArray("series");for(int i=0;i<series.length();i++){JSONObject s=series.getJSONObject(i);if(!s.has("indicator")||s.isNull("indicator"))continue;String id=s.getString("indicator"),output=s.optString("output","value");outputs.put(id+":"+output,e.command("indicatorValues",id,output));}JSONObject layout=e.scene(1200,700).getJSONObject("layout");AsyncVerification.normalizeGeometryKey(layout,null);return canonical(new JSONObject().put("state",state).put("outputs",outputs).put("layout",layout).put("saved",new JSONObject(e.saveDrawings())));}
    private void check(boolean value,String reason){if(!value)throw new AssertionError(reason);checks.put(reason);}
    private void same(String actual,String expected,String reason) throws JSONException {if(!actual.equals(expected)){mismatch=new JSONObject().put("actual",new JSONObject(actual)).put("expected",new JSONObject(expected));throw new AssertionError(reason);}checks.put(reason);}
    private void drawing(AsterEngine e) throws JSONException {String id=e.addDrawing(new JSONObject().put("type","trendline").put("points",new JSONArray().put(new JSONObject().put("time",1700000000000L).put("price",100)).put(new JSONObject().put("time",1700000600000L).put("price",101))));e.editDrawing(id,new JSONObject().put("text","prepare history 🚀"));e.selectDrawing(id);}
    private void captureBytes(AsterEngine e)throws JSONException {expectedBytes.clear();JSONArray series=((JSONObject)e.command("inspect")).getJSONArray("series");for(int i=0;i<series.length();i++){JSONObject binding=series.getJSONObject(i);if(!binding.has("indicator")||binding.isNull("indicator"))continue;String id=binding.getString("indicator"),output=binding.optString("output","value");expectedBytes.put(id+":"+output,e.indicatorBytes(id,output,0,512));}check(expectedBytes.size()==15,"Synchronous prepare reference has15 full Float64 outputs");}
    private void checkBytes()throws JSONException {for(Map.Entry<String,byte[]> entry:expectedBytes.entrySet()){String[] names=entry.getKey().split(":",2);check(Arrays.equals(source.indicatorBytes(names[0],names[1],0,512),entry.getValue()),"Prepared full Float64 bytes match "+entry.getKey());}expectedBytes.clear();}
    private void shapeChecks()throws JSONException {boolean rejected=false;try{AsterColumns.copyOf(null,new double[1],new double[1],new double[1],new double[1],new double[1]);}catch(IllegalArgumentException expected){rejected=true;}check(rejected,"Null owned column rejected before cloning");rejected=false;try{AsterColumns.copyOf(new double[2],new double[1],new double[2],new double[2],new double[2],new double[2]);}catch(IllegalArgumentException expected){rejected=true;}check(rejected,"Unequal owned column lengths rejected before cloning");rejected=false;try{source.prepareSeededAsync(AsterColumns.MAX_BARS+1,42,200,result->{});}catch(IllegalArgumentException expected){rejected=true;}check(rejected,"Count above native resource bound rejected on owner");rejected=false;try{source.prepareSeededAsync(512,42,0,result->{});}catch(IllegalArgumentException expected){rejected=true;}check(rejected,"Zero visibleBars rejected before native job");}
    private AsterEngine.AsyncListener listener(Consumer<AsterEngine.AsyncResult> callback){return new AsterEngine.AsyncListener(){@Override public void onProgress(AsterEngine.AsyncProgress progress){if(!progress.phase.equals("ui-copy"))return;try{check(Looper.myLooper()==Looper.getMainLooper(),"UI copy progress delivered on main owner");check(progress.done>=0&&progress.done<=progress.total,"UI copy progress stays within frame reference count");}catch(Throwable error){finish(error);}}@Override public void onComplete(AsterEngine.AsyncResult result){try{check(Looper.myLooper()==Looper.getMainLooper(),"prepare terminal callback on main owner");long refs=result.metrics.getLong("uiReferences"),total=result.metrics.getLong("uiTotalReferences");check(refs>=0&&refs<=total&&(!result.succeeded()||refs==total),"UI worker reference metrics are bounded and complete on success");jobs.put(result.toJSON());callback.accept(result);}catch(Throwable error){finish(error);}}};}
    void run(Context context,AsterEngine engine,Consumer<JSONObject> completion){this.context=context;source=engine;this.completion=completion;try{
        shapeChecks();source.invoke("nativeInit",0,options());indicators(source);drawing(source);double[][] raw=fixture(512);AsterColumns owned=AsterColumns.copyOf(raw[0],raw[1],raw[2],raw[3],raw[4],raw[5]);
        AsterEngine reference=new AsterEngine(context,0,options());try{indicators(reference);drawing(reference);reference.setColumns(columns(raw));reference.invoke("nativeView",383.5,511.5);reference.setTheme(new JSONObject().put("background","#19283a"));expected=probe(reference);captureBytes(reference);}finally{reference.close();}
        raw[4][7]=9999;raw[2][7]=9999;for(int slot=0;slot<6;slot++)raw[slot][511]+=slot==0?60000:9999;source.prepareColumnsAsync(owned,128,new AsterEngine.AsyncOptions(30000,64),listener(result->{try{
            check(result.succeeded(),"owned raw initial prepare succeeds");same(probe(source),expected,"all 15 JSON vectors/raw-tail/range/view/drawing/UI match sync reference");checkBytes();boolean rejected=false;try{source.indicatorBytes("sma","value",511,2);}catch(IllegalStateException expected){rejected=true;}check(rejected,"Native byte slice beyond logical output rejects safely");check(source.indicatorBytes("sma","value",0,512).length==4096,"Native output remains usable after slice error");String saved=source.saveDrawings();source.undo();check(!source.saveDrawings().equals(saved),"prepare preserves undo history");source.redo();check(source.saveDrawings().equals(saved),"prepare preserves redo history");testInvalid();
        }catch(Throwable error){finish(error);}}));source.setTheme(new JSONObject().put("background","#19283a"));
    }catch(Throwable error){finish(error);}}
    private void testInvalid() throws JSONException {before=probe(source);double[][] raw=fixture(512);raw[2][256]=-1;AsterColumns invalid=AsterColumns.copyOf(raw[0],raw[1],raw[2],raw[3],raw[4],raw[5]);source.prepareColumnsAsync(invalid,128,listener(result->{try{check(result.status.equals("failed"),"middle invalid OHLC rejected in worker");same(probe(source),before,"invalid initial input leaves source exact state unchanged");testCancel();}catch(Throwable error){finish(error);}}));}
    private void testCancel() throws JSONException {before=probe(source);AsterEngine.AsyncJob job=source.prepareSeededAsync(1024,42,128,listener(result->{try{check(result.status.equals("cancelled"),"prepare cancelled before generation");same(probe(source),before,"prepare cancellation leaves original state");testStale();}catch(Throwable error){finish(error);}}));job.cancel();}
    private void testStale() throws JSONException {source.prepareSeededAsync(1024,42,128,listener(result->{try{check(result.status.equals("stale"),"prepare data revision rejects stale completion");same(probe(source),before,"stale prepare preserves newer correction");testTimeout();}catch(Throwable error){finish(error);}}));source.applyDataEvent((JSONObject)source.invoke("nativeBenchmarkEvent",256));source.scene(1200,700);before=probe(source);}
    private void testTimeout() throws JSONException {before=probe(source);source.prepareSeededAsync(1024,42,128,new AsterEngine.AsyncOptions(1,1),listener(result->{try{check(result.status.equals("timedOut"),"prepare timeout terminal");same(probe(source),before,"prepare timeout keeps source unchanged");testFollowFalse();}catch(Throwable error){finish(error);}}));}
    private void testFollowFalse() throws Exception {source.invoke("nativeView",30,100);JSONObject view=((JSONObject)source.command("inspect")).getJSONObject("view");String saved=canonical(new JSONObject(source.saveDrawings()));AsterEngine reference=new AsterEngine(context,512,options());try{indicators(reference);captureBytes(reference);}finally{reference.close();}source.prepareSeededAsync(512,42,64,listener(result->{try{check(result.succeeded(),"seeded prepare succeeds");checkBytes();JSONObject after=(JSONObject)source.command("inspect");check(canonical(after.getJSONObject("view")).equals(canonical(view)),"follow false preserves current viewport");check(canonical(new JSONObject(source.saveDrawings())).equals(saved),"seeded prepare keeps drawing document");source.invoke("nativeResize",777,555);check(source.scene(777,555).getInt("width")==777,"prepared context handles resize");testHeavyUI();}catch(Throwable error){finish(error);}}));}
    private void testHeavyUI() throws JSONException {JSONArray records=new JSONArray();for(int record=0;record<100;record++){JSONArray points=new JSONArray();for(int p=0;p<1000;p++)points.put(new JSONObject().put("time",1700000000000d+p*60000d).put("price",10000+record*0.1+p*0.001));records.put(new JSONObject().put("id","ui-"+record).put("type","freehand").put("panel","price").put("points",points));}source.loadDrawings(new JSONObject().put("schema","aster.drawings").put("version",1).put("drawings",records).toString());String saved=canonical(new JSONObject(source.saveDrawings()));source.prepareSeededAsync(512,42,64,listener(result->{try{check(result.succeeded(),"100 valid freehands with100000 anchors transfer through staged UI");check(result.metrics.getLong("uiChunks")>=50,"large UI split into bounded chunks");check(canonical(new JSONObject(source.saveDrawings())).equals(saved),"staged UI preserves every drawing anchor/style");testCancelUI();}catch(Throwable error){finish(error);}}));}
    private void testCancelUI() throws JSONException {before=probe(source);final AsterEngine.AsyncJob[] job={null};job[0]=source.prepareSeededAsync(512,42,64,new AsterEngine.AsyncListener(){@Override public void onProgress(AsterEngine.AsyncProgress progress){if(progress.phase.equals("ui-capture"))job[0].cancel();}@Override public void onComplete(AsterEngine.AsyncResult result){try{jobs.put(result.toJSON());check(result.status.equals("cancelled"),"cancel during staged UI capture");same(probe(source),before,"UI capture cancellation preserves full original state");testStaleUI();}catch(Throwable error){finish(error);}}});}
    private void testStaleUI() throws JSONException {final boolean[] changed={false};source.prepareSeededAsync(512,42,64,new AsterEngine.AsyncListener(){@Override public void onProgress(AsterEngine.AsyncProgress progress){if(progress.phase.equals("ui-capture")&&!changed[0]){changed[0]=true;try{source.setText("Changed during UI capture");before=probe(source);}catch(Throwable error){finish(error);}}}@Override public void onComplete(AsterEngine.AsyncResult result){try{jobs.put(result.toJSON());check(changed[0]&&result.status.equals("stale"),"UI mutation rejects stale staged capture");same(probe(source),before,"stale UI transfer preserves latest source state");testClose();}catch(Throwable error){finish(error);}}});}
    private void testClose() throws Exception {AsterEngine closing=new AsterEngine(context,0,options());indicators(closing);closing.prepareSeededAsync(1024,42,128,listener(result->{try{check(result.status.equals("closed"),"source close cleans initial prepare once");source.invoke("nativeInit",10000);finish(null);}catch(Throwable error){finish(error);}}));closing.close();}
    private void finish(Throwable error){if(finished)return;finished=true;expectedBytes.clear();try{JSONObject report=new JSONObject().put("passed",error==null?checks.length():0).put("checks",checks).put("jobs",jobs).put("physicalDevice",false).put("inputCopyContract","copyOf clones six private arrays on calling thread; mutation of every caller column after copy does not change snapshot").put("vectorProof","Raw-owned and seeded512-bar cases compare all15 full Float64 byte vectors including NaN payload/signedzero; raw-owned JSON probe separately compares layout/view/UI/drawings and raw tail. Heavy UI cases compare all100000 anchors but place prices offscreen; visible100k-point Canvas rendering cost is outside this fixture.");if(error!=null)report.put("failed",true).put("error",error.toString());if(mismatch!=null)report.put("probeMismatch",mismatch);completion.accept(report);}catch(JSONException jsonError){throw new IllegalStateException(jsonError);}}
}
